function hitungHarga(harga, diskon) {
  return harga - (harga * diskon / 100);
}

// Developer lain memanggil fungsi ini
hitungHarga('50000', 10);  // harga dikirim sebagai string!
// Hasilnya: '50000' - 500 = '50000500'  😱
// Tidak ada error, tapi hasilnya jelas salah

function tampilkanProfil(user) {
  console.log(user.nama);
  console.log(user.emial); // typo! harusnya 'email'
  // JS tidak protes, cuma print 'undefined'
}

tampilkanProfil({ nama: 'Budi', email: 'budi@mail.com' });
// Output:
// Budi
// undefined  ← bug tersembunyi!

