interface User {
  nama: string;
  email: string;
}

function tampilkanProfil(user: User) {
  console.log(user.nama);
  console.log(user.emial);
  // ❌ Error: Property 'emial' does not exist on type 'User'.
  //          Did you mean 'email'?
  // TS bahkan kasih saran perbaikannya!
}

interface Produk {
  nama: string;
  harga: number;
  stok: number;
}

function formatHarga(produk: Produk): string {
  if (produk.stok === 0) {
    return `${produk.nama} — Habis`;
  }
  return `${produk.nama} — Rp ${produk.harga.toLocaleString('id-ID')}`;
}

// Semua tipe hilang, tapi logikanya sama persis
function formatHarga(produk) {
  if (produk.stok === 0) {
    return `${produk.nama} — Habis`;
  }
  return `${produk.nama} — Rp ${produk.harga.toLocaleString('id-ID')}`;
}

langkah_setup.kode:
{
  "compilerOptions": {
    // Target: JS versi berapa yang dihasilkan?
    // 'ES2020' sudah aman untuk browser/Node modern
    "target": "ES2020",

    // Module system yang digunakan
    // 'ESNext' untuk Vite/modern bundler
    // 'CommonJS' untuk Node.js legacy
    "module": "ESNext",

    // Folder hasil compile .js disimpan di mana
    "outDir": "./dist",

    // Folder source .ts kamu
    "rootDir": "./src",

    // strict: true — aktifkan semua pengecekan ketat
    // SELALU nyalakan ini di project baru!
    // Ini mencakup: noImplicitAny, strictNullChecks, dll
    "strict": true,

    // Izinkan import file .json langsung
    "resolveJsonModule": true,

    // Untuk interoperabilitas dengan CommonJS modules
    "esModuleInterop": true
  },
  "include": ["src/**/*"],   // file yang dikompilasi
  "exclude": ["node_modules"] // file yang dilewati
}
